cssAppend:
/* Full plane labels stay readable over every photographic/scroll position. */
.d-parallax[data-mode="full"] .d-parallax-layer>.d-parallax-label{background:#151515;text-shadow:none}
.stage[data-stage-theme="light"] .d-parallax[data-mode="full"] .d-parallax-layer>.d-parallax-label{background:#f4f4f4;color:#626262}
.stage[data-stage-theme="light"] .d-parallax[data-mode="full"] .d-parallax-front>.d-parallax-label{color:#b04a0b}
